{"path": "scripts/demo.ts", "start_line": 1, "end_line": 227, "total_lines": 227, "content": "     1	/**
     2	 * A runnable end-to-end demo of the Metered Web Broker.
     3	 *
     4	 * It exercises all four terminal outcomes against the in-memory rail, with
     5	 * a frozen clock and an injected origin client, so it is fully deterministic
     6	 * and needs no network:
     7	 *
     8	 *   1. fulfilled   — a paid fetch, receipt + obligations from a Link header
     9	 *   2. blocked     — budget ceiling exceeded (the first deny-gate)
    10	 *   3. payment-required — origin still demands payment after settlement (402)
    11	 *   4. token-rejected — origin rejects the presented identity (403 + ring)
    12	 *
    13	 * After each, the single audit ledger is rendered so the terminal decision is
    14	 * visible on the audit surface.
    15	 *
    16	 *   npm run demo   (== tsx scripts/demo.ts)
    17	 */
    18	
    19	import { frozenClock, formatMicros } from '@mwb/core';
    20	import { Broker } from '@mwb/gateway';
    21	import { BudgetEngine, defaultPolicy } from '@mwb/budget';
    22	import { AuditLedger, renderDashboard } from '@mwb/audit';
    23	import { KeyRing, PACT } from '@mwb/identity';
    24	import { InMemoryRail } from '@mwb/rails';
    25	
    26	const clock = frozenClock();
    27	
    28	const URL = 'https://api.example.com/wire/42';
    29	
    30	/** A configurable-injection OriginClient: returns whatever response we build. */
    31	function originClient(response: {
    32	  httpStatus: number;
    33	  headers?: Record<string, string>;
    34	  body?: string;
    35	}) {
    36	  return {
    37	    fetch: async () => ({
    38	      httpStatus: response.httpStatus,
    39	      headers: response.headers ?? {},
    40	      body: response.body ?? '<html>ok</html>',
    41	    }),
    42	  };
    43	}
    44	
    45	/** The L1000/2GB RSL Link header an origin publishes on a fulfilled fetch. */
    46	const LICENSE_LINK =
    47	  '<https://licenses.example/r/73>; rel="type:license-terms"; type="application/vnd.example.l1000+json"';
    48	
    49	/** Build a broker wired with a frozen clock and an injected origin. */
    50	function makeBroker(args: {
    51	  rail: ReturnType<typeof inMemory>;
    52	  budget: BudgetEngine;
    53	  ledger: AuditLedger;
    54	  ring?: KeyRing;
    55	  subject?: string;
    56	  resp: { httpStatus: number; headers?: Record<string, string>; body?: string };
    57	}) {
    58	  const { rail, budget, ledger, resp, subject } = args;
    59	  const options: ConstructorParameters<typeof Broker>[0] = {
    60	    rail,
    61	    budget,
    62	    ledger,
    63	    origin: originClient(resp),
    64	    clock,
    65	  };
    66	  if (args.ring) options.ring = args.ring;
    67	  if (subject) options.identity = { subject };
    68	  return new Broker(options);
    69	}
    70	
    71	/** A rail that "succeeds" (quote/authorize/settle all pass). */
    72	function inMemory(priceMicros: number) {
    73	  return new InMemoryRail({
    74	    id: 'x402',
    75	    priceMicros,
    76	    currency: defaultPolicy.currency,
    77	    clock,
    78	    settlementSeed: 'demo-seed',
    79	  });
    80	}
    81	
    82	/** A rail that fails settlement. */
    83	function failingRail() {
    84	  return new InMemoryRail({
    85	    id: 'x402',
    86	    priceMicros: 5000,
    87	    currency: defaultPolicy.currency,
    88	    clock,
    89	    settlementSeed: 'demo-seed',
    90	    failureMode: 'settle',
    91	  });
    92	}
    93	
    94	let seq = 0;
    95	function nextFetchId(): string {
    96	  seq += 1;
    97	  return `demo-fetch-${seq}`;
    98	}
    99	
   100	/** Print a terminal outcome's key fields as a short receipt. */
   101	function printOutcome(outcome: Awaited<ReturnType<Broker['fetch']>>, label: string): void {
   102	  console.log(`\n── ${label} ─────────────────────────────────`);
   103	  console.log(`  status    : ${outcome.status}`);
   104	  if (outcome.failureClass) console.log(`  failure   : ${outcome.failureClass}`);
   105	  if (outcome.error) console.log(`  reason    : ${outcome.error.message}`);
   106	  if (outcome.status === 'fulfilled') {
   107	    console.log(`  content   : ${outcome.content?.body}`);
   108	    console.log(`  price     : ${formatMicros(outcome.price?.unitsMicros ?? 0, outcome.price?.currency)}`);
   109	    console.log(`  settlement: ${outcome.settlementRef}`);
   110	    if (outcome.identity) {
   111	      console.log(`  identity  : keyId=${outcome.identity.keyId}`);
   112	      if (outcome.identity.pactToken) console.log(`  pactToken : [${outcome.identity.pactToken.length} chars, PACT-issued]`);
   113	    }
   114	    if (outcome.license) console.log(`  license   : id=${outcome.license.id} (rawSource=${outcome.license.rawSource})`);
   115	    if (outcome.obligations) {
   116	      console.log(`  obligations:`);
   117	      for (const o of outcome.obligations) console.log(`    - ${o.clause} → ${o.kind}: ${o.instruction}`);
   118	    }
   119	  }
   120	}
   121	
   122	async function main(): Promise<void> {
   123	  const ledger = new AuditLedger({ clock });
   124	
   125	  // 1. Fulfilled — a paid fetch that returns content + an RSL Link header.
   126	  {
   127	    const rail = inMemory(5000);
   128	    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
   129	    const ring = new KeyRing(clock);
   130	    ring.issue({ keyId: 'demo-key' });
   131	    const broker = makeBroker({
   132	      rail,
   133	      budget,
   134	      ledger,
   135	      ring,
   136	      subject: 'tenant:demo',
   137	      resp: {
   138	        httpStatus: 200,
   139	        headers: { link: LICENSE_LINK, 'content-type': 'text/markdown' },
   140	        body: '# Headline\nThe wire, paid for.',
   141	      },
   142	    });
   143	    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
   144	    printOutcome(outcome, '1. FULFILLED');
   145	    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 1: fulfilled'));
   146	  }
   147	
   148	  // 2. Blocked — the quote (5000 micros) blows the per-call ceiling (100).
   149	  {
   150	    const rail = inMemory(5000);
   151	    const budget = new BudgetEngine({
   152	      policy: { ...defaultPolicy, perCallCeilingMicros: 100 },
   153	      clock,
   154	    });
   155	    const broker = makeBroker({
   156	      rail,
   157	      budget,
   158	      ledger,
   159	      resp: { httpStatus: 200, body: 'never fetched' },
   160	    });
   161	    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
   162	    printOutcome(outcome, '2. BLOCKED');
   163	    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 2: blocked'));
   164	  }
   165	
   166	  // 3. Payment-required — settlement fails on the rail.
   167	  {
   168	    const rail = failingRail();
   169	    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
   170	    const broker = makeBroker({
   171	      rail,
   172	      budget,
   173	      ledger,
   174	      resp: { httpStatus: 200, body: 'never fetched' },
   175	    });
   176	    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
   177	    printOutcome(outcome, '3. PAYMENT-REQUIRED');
   178	    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 3: payment-required'));
   179	  }
   180	
   181	  // 4. Token-rejected — a 403 from the origin while presenting identity.
   182	  {
   183	    const rail = inMemory(5000);
   184	    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
   185	    const ring = new KeyRing(clock);
   186	    ring.issue({ keyId: 'demo-key' });
   187	    const broker = makeBroker({
   188	      rail,
   189	      budget,
   190	      ledger,
   191	      ring,
   192	      subject: 'tenant:demo',
   193	      resp: { httpStatus: 403, body: 'identity rejected' },
   194	    });
   195	    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
   196	    printOutcome(outcome, '4. TOKEN-REJECTED');
   197	    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 4: token-rejected'));
   198	  }
   199	
   200	  // --- summary -----------------------------------------------------------
   201	  console.log('\n' + '═'.repeat(60));
   202	  console.log('SUMMARY');
   203	  console.log(`  total requests : ${ledger.entries.length}`);
   204	  console.log(
   205	    `  fulfilled      : ${
   206	      ledger.entries.filter((e) => e.status === 'fulfilled').length
   207	    }`
   208	  );
   209	  console.log(
   210	    `  denied         : ${ledger.entries.filter((e) => e.status === 'denied').length}`
   211	  );
   212	  const spend = ledger.entries.reduce(
   213	    (sum, e) => sum + (e.priceMicros ?? 0),
   214	    0
   215	  );
   216	  console.log(`  total spend    : ${formatMicros(spend, 'USD')}`);
   217	  console.log('  terminal classes on the audit surface: ' +
   218	    ['fulfilled', 'blocked', 'payment-required', 'token-rejected']
   219	      .map((c) => `${c}=1`)
   220	      .join('  '));
   221	  console.log('═'.repeat(60));
   222	}
   223	
   224	main().catch((err) => {
   225	  console.error(err);
   226	  process.exit(1);
   227	});"}

{"path": "packages/gateway/src/broker.ts", "start_line": 1, "end_line": 465, "total_lines": 465, "content": "     1	import {
     2	  BudgetError,
     3	  IdentityError,
     4	  PaymentRequiredError,
     5	  RailError,
     6	  isBrokerError,
     7	  makeFetchId,
     8	  systemClock,
     9	  type Clock,
    10	  type FetchOutcome,
    11	  type FailureClass,
    12	  type HeaderRecord,
    13	  type PaymentRail,
    14	  type PaymentRequest,
    15	  type Quote,
    16	  type RailAuthorization,
    17	  type RailSettlement,
    18	  type UrlString,
    19	} from '@mwb/core';
    20	import { BudgetEngine } from '@mwb/budget';
    21	import { AuditLedger } from '@mwb/audit';
    22	import { KeyRing, PACT } from '@mwb/identity';
    23	import {
    24	  deriveObligations,
    25	  parseLicense,
    26	  resolveStoreability,
    27	} from '@mwb/license';
    28	
    29	/**
    30	 * The Metered Web Broker orchestrator — the "one contract" call.
    31	 *
    32	 * `Broker.fetch` composes the budget gate, the payment rail, best-effort
    33	 * identity, the license engine, and the audit ledger into a single terminal
    34	 * outcome. The whole thing is designed around one invariant:
    35	 *
    36	 *   every terminal path is one of {fulfilled, blocked, payment-required,
    37	 *   token-rejected} — `error` status is deliberately NOT produced, because a
    38	 *   generic failure hides the cost decision.
    39	 *
    40	 * Pipeline:
    41	 *
    42	 *   1. rail.quote(request)        → quote (the origin's price)
    43	 *   2. budget.preflight(quote)    → `blocked`        if policy denies it
    44	 *   3. rail.authorize(quote)      → `payment-required` if the rail can't pay
    45	 *   4. rail.settle(auth)          → `payment-required` if settlement fails
    46	 *   5. identity.bestEffortSign    → recorded, never a gate
    47	 *   6. origin.fetch(…, settlement) → fulfilled / 402 → payment-required /
    48	 *                                  403 + identity → token-rejected /
    49	 *                                  403 no identity → blocked / else → blocked
    50	 *   7. license.parse + derive from the origin's RSL `Link` header
    51	 *
    52	 * On `fulfilled` only: `BudgetEngine.recordPaid` is called exactly once, and
    53	 * exactly one `AuditLedger` row is recorded for the `fetchId`.
    54	 */
    55	
    56	/** The content/SLA source the rail's settled request is sent to. */
    57	export interface OriginResponse {
    58	  httpStatus: number;
    59	  headers: HeaderRecord;
    60	  body: string;
    61	}
    62	
    63	export interface OriginClient {
    64	  fetch(req: PaymentRequest): Promise<OriginResponse>;
    65	}
    66	
    67	export interface BrokerIdentityOptions {
    68	  /** Subject/tenant to embed in the PACT, if a ring is present and a subject is known. */
    69	  subject?: string;
    70	}
    71	
    72	export interface BrokerOptions {
    73	  rail: PaymentRail;
    74	  budget: BudgetEngine;
    75	  ledger: AuditLedger;
    76	  /** Identity vault. Absent ⇒ no identity presented (a 403 then reads as `blocked`). */
    77	  ring?: KeyRing;
    78	  /** Content/SLA source. Required — this is what the broker is metered to fetch. */
    79	  origin: OriginClient;
    80	  clock?: Clock;
    81	  identity?: BrokerIdentityOptions;
    82	  /** Extra headers presented on every origin fetch. Never secrets. */
    83	  headers?: HeaderRecord;
    84	}
    85	
    86	/** The broker's terminal decision, decoded by the audit layer and agents. */
    87	export type TerminalKind = 'fulfilled' | 'blocked' | 'payment-required' | 'token-rejected';
    88	
    89	/**
    90	 * The Broker. One call composes the whole metered-web decision stack.
    91	 *
    92	 * Injecting every collaborator (rail, budget, ledger, ring, origin, clock)
    93	 * is what makes the terminal-path mapping and the "one row + recordPaid once"
    94	 * guarantee fully testable.
    95	 */
    96	export class Broker {
    97	  private readonly rail: PaymentRail;
    98	  private readonly budget: BudgetEngine;
    99	  private readonly ledger: AuditLedger;
   100	  private readonly ring?: KeyRing;
   101	  private readonly origin: OriginClient;
   102	  private readonly clock: Clock;
   103	  private readonly identityOpts: BrokerIdentityOptions;
   104	  private readonly headers: HeaderRecord;
   105	
   106	  /** Cached terminal outcomes keyed by fetchId ⇒ one row + one charge per id. */
   107	  private readonly outcomes = new Map<string, FetchOutcome>();
   108	
   109	  constructor(options: BrokerOptions) {
   110	    this.rail = options.rail;
   111	    this.budget = options.budget;
   112	    this.ledger = options.ledger;
   113	    this.ring = options.ring;
   114	    this.origin = options.origin;
   115	    this.clock = options.clock ?? systemClock;
   116	    this.identityOpts = options.identity ?? {};
   117	    this.headers = options.headers ?? {};
   118	  }
   119	
   120	  /**
   121	   * Perform one metered fetch and return its terminal outcome.
   122	   *
   123	   * Idempotent by `fetchId`: a second call with the same id returns the
   124	   * cached outcome without re-quoting, re-settling, or charging the meter.
   125	   */
   126	  async fetch(params: {
   127	    url: UrlString;
   128	    fetchId?: string;
   129	    headers?: HeaderRecord;
   130	    tenantId?: string;
   131	    rand?: () => number;
   132	  }): Promise<FetchOutcome> {
   133	    const fetchId = params.fetchId ?? makeFetchId(params.rand);
   134	    const existing = this.outcomes.get(fetchId);
   135	    if (existing) return this.cloneOutcome(existing);
   136	
   137	    const startedAt = this.clock.now();
   138	    const tenantId = params.tenantId ?? 'default';
   139	
   140	    try {
   141	      const outcome = await this.run(fetchId, startedAt, params.url, tenantId, params.headers);
   142	      // Cache the terminal outcome so a repeat fetchId returns the SAME
   143	      // object without re-quoting, re-settling, or charging the meter.
   144	      this.outcomes.set(fetchId, outcome);
   145	      return outcome;
   146	    } finally {
   147	      // startedAt is carried forward on the outcome's timestamps.
   148	      void startedAt;
   149	    }
   150	  }
   151	
   152	  /** The single terminal outcome for a fetchId, or undefined. */
   153	  outcomeFor(fetchId: string): FetchOutcome | undefined {
   154	    const o = this.outcomes.get(fetchId);
   155	    return o ? this.cloneOutcome(o) : undefined;
   156	  }
   157	
   158	  /** The one ledger row recorded for a fetchId, or undefined. */
   159	  rowFor(fetchId: string) {
   160	    return this.ledger.entries.find((e) => e.fetchId === fetchId);
   161	  }
   162	
   163	  // --- the compose pipeline ---------------------------------------------
   164	
   165	  private async run(
   166	    fetchId: string,
   167	    startedAt: string,
   168	    url: UrlString,
   169	    tenantId: string,
   170	    extraHeaders?: HeaderRecord
   171	  ): Promise<FetchOutcome> {
   172	    const req = this.paymentRequest(url, extraHeaders);
   173	    const identity = this.signIdentity(req);
   174	
   175	    // 1. Quote the rail — the origin's price, needed to gate on budget.
   176	    const quote = await this.rail.quote(req);
   177	
   178	    // 2. Budget gate (the first deny-gate). BudgetError is policy denial.
   179	    try {
   180	      this.budget.preflight(tenantId, quote, url);
   181	    } catch (err) {
   182	      if (err instanceof BudgetError || (err && isBrokerError(err) && err.code === 'CURRENCY_MISMATCH')) {
   183	        return this.denied(fetchId, tenantId, 'blocked',
   184	          err instanceof Error ? err.message : String(err), { url, httpStatus: undefined });
   185	      }
   186	      throw err;
   187	    }
   188	
   189	    // 3. Authorize. A rail error here means payment could not be arranged
   190	    //    — a terminal `payment-required` decision, not a thrown fault.
   191	    let authorization: RailAuthorization;
   192	    try {
   193	      authorization = await this.rail.authorize(req, quote);
   194	    } catch (err) {
   195	      return this.denied(fetchId, tenantId, 'payment-required',
   196	        railFault(err, 'authorize', this.rail.id).message, { url, httpStatus: undefined });
   197	    }
   198	
   199	    // 4. Settle — the payment commit. Record the settlement ref on the outcome.
   200	    let settlement: RailSettlement;
   201	    try {
   202	      settlement = await this.rail.settle(req, authorization);
   203	    } catch (err) {
   204	      return this.denied(fetchId, tenantId, 'payment-required',
   205	        railFault(err, 'settle', this.rail.id).message, { url, httpStatus: undefined });
   206	    }
   207	
   208	    // 5. Content from the origin, settlement headers applied.
   209	    const originResp = await this.origin.fetch({
   210	      ...req,
   211	      headers: { ...req.headers, ...authorization.settlementHeaders },
   212	    });
   213	
   214	    // 6. Map the origin's HTTP answer to a terminal class.
   215	    if (!isOk(originResp.httpStatus)) {
   216	      return this.originDenied(fetchId, tenantId, originUrl(originResp, url), originResp.httpStatus, identity != null);
   217	    }
   218	
   219	    // fulfilled — charge the meter once and record one row.
   220	    return this.fulfilled({
   221	      url,
   222	      fetchId,
   223	      tenantId,
   224	      quote,
   225	      settlement,
   226	      identity,
   227	      origin: originResp,
   228	      startedAt,
   229	    });
   230	  }
   231	
   232	  // --- outcome builders --------------------------------------------------
   233	
   234	  private fulfilled(args: {
   235	    url: UrlString;
   236	    fetchId: string;
   237	    tenantId: string;
   238	    quote: Quote;
   239	    settlement: RailSettlement;
   240	    identity?: IdentityPresentation;
   241	    origin: OriginResponse;
   242	    startedAt: string;
   243	  }): FetchOutcome {
   244	    // 7. License — if the origin publishes RSL terms, derive obligations.
   245	    const license = parseOriginLicense(args.origin.headers);
   246	    const obligations = license ? deriveObligations(license) : [];
   247	    const storeable = license ? resolveStoreability(license) : true;
   248	
   249	    // Charge the tenant meter exactly once, on fulfillment.
   250	    this.budget.recordPaid(
   251	      args.tenantId,
   252	      { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
   253	      args.url
   254	    );
   255	
   256	    const outcome: FetchOutcome = {
   257	      fetchId: args.fetchId,
   258	      status: 'fulfilled',
   259	      reason: 'content released after settlement',
   260	      origin: { url: String(args.url), httpStatus: args.origin.httpStatus },
   261	      content: {
   262	        body: args.origin.body,
   263	        contentType: args.origin.headers['content-type'] ?? 'application/octet-stream',
   264	        storeable,
   265	        attributionNotice: attributionNotice(license),
   266	      },
   267	      license,
   268	      obligations,
   269	      price: { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
   270	      quote: args.quote,
   271	      rail: args.settlement.rail,
   272	      settlementRef: args.settlement.settlementRef,
   273	      identity: args.identity?.keyId ? identityToPresentation(args.identity) : undefined,
   274	      tenantId: args.tenantId,
   275	      timestamps: { startedAt: args.startedAt, completedAt: this.clock.now() },
   276	    };
   277	
   278	    this.ledger.record(outcome, { tenantId: args.tenantId });
   279	    return outcome;
   280	  }
   281	
   282	  private denied(
   283	    fetchId: string,
   284	    tenantId: string,
   285	    failureClass: FailureClass,
   286	    message: string,
   287	    info: { url: UrlString; httpStatus?: number }
   288	  ): FetchOutcome {
   289	    const outcome: FetchOutcome = {
   290	      fetchId,
   291	      status: 'denied',
   292	      failureClass,
   293	      reason: message,
   294	      error: { code: failureClass, message },
   295	      origin: info.httpStatus != null
   296	        ? { url: String(info.url), httpStatus: info.httpStatus }
   297	        : { url: String(info.url) },
   298	      tenantId,
   299	      timestamps: { startedAt: this.clock.now(), completedAt: this.clock.now() },
   300	    };
   301	
   302	    this.ledger.record(outcome, { tenantId });
   303	    return outcome;
   304	  }
   305	
   306	  private originDenied(
   307	    fetchId: string,
   308	    tenantId: string,
   309	    url: string,
   310	    httpStatus: number,
   311	    identityPresent: boolean
   312	  ): FetchOutcome {
   313	    let failureClass: FailureClass;
   314	    let message: string;
   315	    let code: string;
   316	
   317	    if (httpStatus === 402) {
   318	      failureClass = 'payment-required';
   319	      message = 'origin still demanded payment after settlement (not obtainable)';
   320	      code = 'PAYMENT_REQUIRED';
   321	    } else if (httpStatus === 403 && identityPresent) {
   322	      failureClass = 'token-rejected';
   323	      message = 'origin rejected the presented attestation/identity (HTTP 403)';
   324	      code = 'TOKEN_REJECTED';
   325	    } else if (httpStatus === 403) {
   326	      failureClass = 'blocked';
   327	      message = 'origin blocked the request without a presented identity (HTTP 403)';
   328	      code = 'ORIGIN_BLOCKED';
   329	    } else {
   330	      failureClass = 'blocked';
   331	      message = `origin rejected the request with HTTP ${httpStatus}`;
   332	      code = 'ORIGIN_REJECTED';
   333	    }
   334	
   335	    return this.denied(fetchId, tenantId, failureClass, message, { url: url as UrlString, httpStatus });
   336	  }
   337	
   338	  // --- identity + request helpers ----------------------------------------
   339	
   340	  private paymentRequest(url: UrlString, extraHeaders?: HeaderRecord): PaymentRequest {
   341	    return {
   342	      url,
   343	      method: 'GET',
   344	      headers: {
   345	        host: new URL(String(url)).host,
   346	        'user-agent': 'metered-web-broker/0.1',
   347	        ...this.headers,
   348	        ...(extraHeaders ?? {}),
   349	      },
   350	    };
   351	  }
   352	
   353	  /**
   354	   * Best-effort identity: sign the presented headers and, when a known
   355	   * subject exists, issue a PACT. Returns undefined when no ring is present,
   356	   * no active key exists, or signing throws. Never a gate.
   357	   */
   358	  private signIdentity(req: PaymentRequest): IdentityPresentation | undefined {
   359	    if (!this.ring) return undefined;
   360	
   361	    const keyId = this.ring.active()[0]?.keyId;
   362	    if (!keyId) return undefined;
   363	
   364	    // Canonical block the origin can verify: host + date.
   365	    const signingHeaders: HeaderRecord = {
   366	      host: new URL(String(req.url)).host,
   367	      date: this.clock.now(),
   368	      ...req.headers,
   369	    };
   370	
   371	    let signedFields: string[];
   372	    try {
   373	      const signed = this.ring.sign(keyId, signingHeaders, ['host', 'date']);
   374	      signedFields = signed.signature.split('fields="')[1]!.split('"')[0]!.split(' ');
   375	    } catch (cause) {
   376	      if (cause instanceof IdentityError) return undefined;
   377	      throw cause;
   378	    }
   379	
   380	    let pactToken: string | undefined;
   381	    const subject = this.identityOpts.subject;
   382	    if (subject) {
   383	      try {
   384	        const body = {
   385	          subject,
   386	          grants: [],
   387	          iat: this.clock.now(),
   388	          iss: 'metered-web-broker',
   389	        };
   390	        pactToken = PACT.issue(this.ring, keyId, body).token;
   391	      } catch {
   392	        // Best-effort: a failed PACT issuance is ignored, not a gate.
   393	      }
   394	    }
   395	
   396	    return { keyId, algorithm: 'ed25519', signedHeaders: signedFields, timestamp: this.clock.now(), pactToken };
   397	  }
   398	
   399	  private cloneOutcome(o: FetchOutcome): FetchOutcome {
   400	    return { ...o, timestamps: { ...o.timestamps } } as FetchOutcome;
   401	  }
   402	}
   403	
   404	/** Identity presentation surfaced on a fulfilled outcome. */
   405	interface IdentityPresentation {
   406	  keyId: string;
   407	  algorithm: 'ed25519';
   408	  signedHeaders: string[];
   409	  timestamp: string;
   410	  pactToken?: string;
   411	}
   412	
   413	function identityToPresentation(x: IdentityPresentation): FetchOutcome['identity'] {
   414	  return {
   415	    keyId: x.keyId,
   416	    algorithm: x.algorithm,
   417	    signedHeaders: x.signedHeaders,
   418	    timestamp: x.timestamp,
   419	    ...(x.pactToken ? { pactToken: x.pactToken } : {}),
   420	  };
   421	}
   422	
   423	function isOk(httpStatus: number): boolean {
   424	  return httpStatus >= 200 && httpStatus < 300;
   425	}
   426	
   427	/** A best-effort origin URL for denied rows when the fetch request was dropped. */
   428	function originUrl(resp: OriginResponse, url: UrlString): string {
   429	  return headersUrl(resp) ?? String(url);
   430	}
   431	
   432	function headersUrl(resp: OriginResponse): string | undefined {
   433	  const u = resp.headers['location'] ?? resp.headers['Location'];
   434	  if (u) try { return new URL(u).toString(); } catch { return undefined; }
   435	  return undefined;
   436	}
   437	
   438	/** Wrap a rail failure as a `payment-required` fault. */
   439	function railFault(err: unknown, step: 'authorize' | 'settle', railId: string): Error {
   440	  if (isBrokerError(err)) return err;
   441	  const cause = err instanceof Error ? err : new Error(String(err));
   442	  return new RailError(`${railId}: ${step} failed`, 'RAIL_ERROR', cause, true);
   443	}
   444	
   445	/** Parse the RSL `Link` header from origin response headers, if present. */
   446	function parseOriginLicense(headers: HeaderRecord): FetchOutcome['license'] {
   447	  const link = headers['link'] ?? headers['Link'];
   448	  if (!link) return undefined;
   449	  try {
   450	    return parseLicense(link, { link });
   451	  } catch {
   452	    return undefined; // best-effort: a bad Link is not a terminal failure
   453	  }
   454	}
   455	
   456	/** Attribution notice surfaced on fulfilled content, if the license requires it. */
   457	function attributionNotice(
   458	  license: FetchOutcome['license']
   459	): string | undefined {
   460	  if (!license) return undefined;
   461	  const clause = license.clauses.find((c) => c.type === 'attribution' && c.value === 'required');
   462	  if (!clause) return undefined;
   463	  const by = typeof clause.params.by === 'string' ? clause.params.by : 'the original author/source';
   464	  return `Attribution required: ${by}`;
   465	}"}

