    29	 * is not a global under the no-DOM base config). Declared locally to keep the
    30	 * runtime footprint honest: no DOM lib required.
    31	 */
    32	export interface OkpJwk {
    33	  kty: 'OKP';
    34	  crv: 'Ed25519';
    35	  x?: string;
    36	  d?: string;
    37	  // crypto's JsonWebKeyInput carries an index signature; keep one so the
    38	  // object literal is structurally assignable without widening the real fields.
    39	  [key: string]: unknown;
    40	}
    41	
    42	export function b64url(bytes: Uint8Array): B64Url {
    43	  return Buffer.from(bytes).toString('base64url');
    44	}
    45	
    46	export function fromB64url(s: B64Url): Uint8Array {
    47	  return new Uint8Array(Buffer.from(s, 'base64url'));
    48	}
    49	
    50	export interface KeyPair {
    51	  /** Broker-chosen stable key id — this is what the audit trail references. */
    52	  keyId: string;
    53	  algorithm: 'ed25519';
    54	  /** 32-byte public key (JWK `x`), base64url. */
    55	  publicRaw: B64Url;
    56	  /** 32-byte seed (JWK `d`), base64url. Never leaves the broker. */
    57	  privateRaw: B64Url;
    58	  createdAt: string;
    59	  expiresAt: string;
    60	  revokedAt?: string;
    61	}
    62	
    63	export interface IssueOptions {
    64	  keyId?: string;
    65	  /** Lifetime. Default 1h; hard cap 24h (tight-expiry discipline). */
    66	  ttlMs?: number;
    67	}
    68	
    69	const MAX_TTL_MS = 24 * 3_600_000;
    70	const DEFAULT_TTL_MS = 3_600_000;
    71	
    72	/**
    73	 * The broker's identity vault. Every key the broker has ever issued, in
    74	 * memory. Keys past `expiresAt` or with `revokedAt` set refuse to sign;
