    76	 */
    77	export class KeyRing {
    78	  readonly clock: Clock;
    79	  private readonly keys = new Map<string, KeyPair>();
    80	  private counter = 0;
    81	
    82	  constructor(clock: Clock = systemClock) {
    83	    this.clock = clock;
    84	  }
    85	
    86	  /** Mint a fresh Ed25519 keypair with tight expiry. */
    87	  issue(options: IssueOptions = {}): KeyPair {
    88	    const now = this.clock.now();
    89	    const nowMs = Date.parse(now);
    90	    const ttl = Math.min(Math.max(1_000, options.ttlMs ?? DEFAULT_TTL_MS), MAX_TTL_MS);
    91	    const { publicKey, privateKey } = generateKeyPairSync('ed25519');
