   104	      algorithm: 'ed25519',
   105	      publicRaw: b64url(fromB64url(pubJwk.x as string)),
   106	      privateRaw: b64url(fromB64url(privJwk.d as string)),
   107	      createdAt: now,
   108	      expiresAt: new Date(nowMs + ttl).toISOString(),
   109	    };
