   116	   * key remains verifiable until the caller drops it — that is what lets
   117	   * in-flight settlements close out cleanly.
   118	   */
   119	  rotate(options: IssueOptions = {}): { previous?: KeyPair; next: KeyPair } {
   120	    const current = this.active().sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
