   141	  /**
   142	   * Sign a canonicalized header block.
   143	   *
   144	   * Canonicalization: lowercase header names, lexicographic order, one
   145	   * `name: value` per line, joined with `\n`, trailing `\n`. This is the
   146	   * *pattern* of http-message-signatures; the exact wire form tracks
   147	   * whatever draft the origin validates against.
   148	   *
   149	   * Returns:
   150	   *  - `signature`: the wire header value to attach
   151	   *  - `message`: the canonical signing string (for replay/debug)
   152	   *  - `signedAt`: broker timestamp
   153	   */
   154	  sign(
   155	    keyId: string,
   156	    headers: HeaderRecord,
   157	    signedFields: string[] = ['host', 'date']
   158	  ): { signature: string; message: string; signedAt: string } {
