   160	    const now = this.clock.now();
   161	    if (kp.revokedAt) throw new IdentityError(`key revoked: ${keyId}`, 'IDENTITY_REVOKED');
   162	    if (Date.parse(kp.expiresAt) < Date.parse(now)) {
