   206	    }
   207	  }
   208	
   209	  /**
   210	   * Directory the broker serves at `/.well-known/agent-identity`. Only
   211	   * active keys appear, sorted by keyId for stable diffs.
   212	   */
   213	  directory(): {
   214	    format: 'agent-identity-directory';
   215	    agentIdentity: Array<{ keyId: string; alg: 'Ed25519'; pubkey: string; expires: string }>;
   216	  } {
