   236	}
   237	
   238	/**
   239	 * A PACT is a broker-issued, key-signed attestation token. Wire format is
   240	 * intentionally minimal:
   241	 *
   242	 *   <base64url(json of claims)> . <keyId> . <base64url(signature)>
   243	 *
   244	 * where the signature covers `<claimsBytes>` exactly (so origin replays
   245	 * the same bytes it received, and the keyId selects the ring entry). When
   246	 * the PACT spec stabilizes, this token shape stays — only the payload
   247	 * inside changes.
   248	 */
   249	export class PACT {
   250	  static issue(ring: KeyRing, keyId: string, claims: Record<string, unknown>): {
   251	    token: string;
   252	    message: string;
   253	    signedAt: string;
   254	  } {
   255	    const body = JSON.stringify(claims);
   256	    const b64 = Buffer.from(body, 'utf8').toString('base64url');
   257	    const sigB64url = b64url(signPactBody(body, ring, keyId));
   258	    return {
   259	      token: `${b64}.${keyId}.${sigB64url}`,
   260	      message: body,
   261	      signedAt: ring.clock.now(),
   262	    };
   263	  }
   264	
   265	  static parse(token: string): { claims: Record<string, unknown>; keyId: string; signature: B64Url; body: string } {
   266	    const parts = token.split('.');
   267	    if (parts.length !== 3) throw new IdentityError('malformed PACT token (expected 3 parts)', 'PACT_MALFORMED');
   268	    const [bodyB64, keyId, signature] = parts as [B64Url, string, B64Url];
   269	    const body = Buffer.from(bodyB64, 'base64url').toString('utf8');
   270	    let claims: Record<string, unknown>;
   271	    try {
   272	      claims = JSON.parse(body) as Record<string, unknown>;
   273	    } catch (cause) {
   274	      throw new IdentityError('PACT claims are not valid JSON', 'PACT_CLAIMS', cause);
   275	    }
   276	    return { claims, keyId, signature, body };
   277	  }
   278	
   279	  static verify(token: string, ring: KeyRing): { valid: boolean; reason?: string; claims?: Record<string, unknown> } {
   280	    const { claims, keyId, signature, body } = PACT.parse(token);
   281	    if (new Date(claims.exp as string).getTime() < Date.parse(ring.clock.now())) {
   282	      return { valid: false, reason: 'pact-expired', claims };
   283	    }
   284	    const ok = signPactVerify(body, ring, keyId, signature);
   285	    if (!ok) return { valid: false, reason: 'signature-mismatch', claims };
   286	    return { valid: true, claims };
   287	  }
   288	}
   289	
   290	/** Sign the exact bytes of a PACT body (not a header canonicalization). */
   291	function signPactBody(body: string, ring: KeyRing, keyId: string): Uint8Array {
   292	  const kp = ring.get(keyId);
   293	  const keyObject = createPrivateKey({
   294	    key: {
   295	      kty: 'OKP',
   296	      crv: 'Ed25519',
   297	      d: kp.privateRaw,
   298	      x: kp.publicRaw,
   299	    } as OkpJwk,
   300	    format: 'jwk',
   301	  });
   302	  return new Uint8Array(sign(null, Buffer.from(body, 'utf8'), keyObject));
   303	}
   304	
   305	function signPactVerify(body: string, ring: KeyRing, keyId: string, sigB64url: B64Url): boolean {
   306	  try {
   307	    const kp = ring.get(keyId);
   308	    const keyObject = createPublicKey({
   309	      key: {
   310	        kty: 'OKP',
   311	        crv: 'Ed25519',
   312	        x: kp.publicRaw,
   313	      } as OkpJwk,
   314	      format: 'jwk',
   315	    });
