   328	function signMessage(keyId: string, message: string, ring: KeyRing): { signature: B64Url } {
   329	  const kp = ring.get(keyId);
   330	  const keyObject = createPrivateKey({
   331	    key: {
   332	      kty: 'OKP',
   333	      crv: 'Ed25519',
   334	      d: kp.privateRaw,
   335	      x: kp.publicRaw,
   336	    } as OkpJwk,
   337	    format: 'jwk',
   338	  });
   339	  return { signature: b64url(new Uint8Array(sign(null, Buffer.from(message, 'utf8'), keyObject))) };
   340	}
   341	
   342	/** Convenience: issue a common-claims PACT with standard expiry. */
   343	export function issuePact(
   344	  ring: KeyRing,
   345	  keyId: string,
   346	  subject: string,
   347	  grants?: Array<{ domain?: string; scope?: string; spendCeilingMicros?: number }>
   348	): { token: string; message: string; signedAt: string } {
   349	  const nowMs = Date.parse(ring.clock.now());
   350	  const body = {
   351	    subject,
   352	    grants: grants ?? [],
   353	    iat: new Date(nowMs).toISOString(),
   354	    exp: new Date(Math.min(nowMs + 15 * 60_000, Date.parse(ring.get(keyId).expiresAt))).toISOString(),
   355	    iss: 'metered-web-broker',
   356	  };
   357	  return PACT.issue(ring, keyId, body);
