{"content": "import {
  ConformanceError,
  type ContractCard,
  type TerminalKind,
  type ValidationResult,
} from './types.js';

/**
 * The four terminal classes the broker reports. Derived in one place so the
 * identity + audit + contract-shape validators agree on the vocabulary.
 */
const TERMINAL_CLASSES: ReadonlySet<string> = new Set<TerminalKind>([
  'fulfilled',
  'blocked',
  'payment-required',
  'token-rejected',
]);

/** The RSL `rel` the broker reads as the published license-terms link. */
const LICENSE_REL = 'type:license-terms';

/**
 * Derive a license id from a Link href the same way the broker's RSL engine
 * does: the href's pathname, not the full href. A bare `/r/73` stays `/r/73`;
 * an absolute `https://licenses.example/r/73` collapses to `/r/73`. Query and
 * hash fragments are dropped, matching the engine's `slugFromUrl`.
 */
function deriveId(href: string): string {
  if (href.startsWith('http://') || href.startsWith('https://')) {
    try {
      return new URL(href).pathname;
    } catch {
      /* fall through and treat the href as a bare path */
    }
  }
  const cut = href.indexOf('?');
  const hash = href.indexOf('#');
  const end = cut === -1 && hash === -1 ? href.length : Math.min(
    cut === -1 ? href.length : cut,
    hash === -1 ? href.length : hash,
  );
  return href.slice(0, end);
}

/** identity — PACT key/pactToken present and structurally consistent. */
function validateIdentity(card: ContractCard): ValidationResult {
  const id = card.identity;
  if (!id || typeof id.keyId !== 'string' || id.keyId.length === 0) {
    return {
      name: 'identity',
      ok: false,
      message: 'a PACT identity claim requires a non-empty keyId',
    };
  }

  // The broker issues a PACT only when a KeyRing AND an identity.subject are
  // both present — so a subject implies a token, and a token implies a subject.
  const subject = typeof id.subject === 'string' && id.subject.length > 0;
  const token = typeof id.pactToken === 'string' && id.pactToken.length > 0;
  if (subject !== token) {
    return {
      name: 'identity',
      ok: false,
      message: `a PACT requires both identity.subject and pactToken (subject present=${subject}, token present=${token})`,
    };
  }

  return {
    name: 'identity',
    ok: true,
    message: `identity PACT consistent (keyId=${id.keyId}${id.subject ? `, subject=${id.subject}` : ''})`,
  };
}

/** license — RSL Link resolves, obligations derive, id is the pathname. */
function validateLicense(card: ContractCard): ValidationResult {
  const license = card.license;
  if (!license) {
    return {
      name: 'license',
      ok: false,
      message: 'no license terms referenced on the fulfilled outcome',
    };
  }

  if (typeof license.id !== 'string' || license.id.length === 0) {
    return { name: 'license', ok: false, message: 'license id is missing' };
  }

  // An RSL `Link` header with rel="type:license-terms" must identify the doc.
  if (card.linkHref !== undefined && card.linkHref !== null) {
    if (card.linkHref.indexOf(LICENSE_REL) === -1) {
      return {
        name: 'license',
        ok: false,
        message: `the RSL Link must carry rel="${LICENSE_REL}" (found: ${card.linkHref})`,
      };
    }
    // id is the href's pathname, not the full href (matches engine slugFromUrl).
    if (deriveId(card.linkHref) !== license.id) {
      return {
        name: 'license',
        ok: false,
        message: `license id must equal the Link href pathname (${deriveId(card.linkHref)}), not the full href`,
      };
    }
  }

  // Obligations derive from the license: clauses present ⇒ obligations present
  // with one entry per clause; absent ⇒ no obligations.
  const clauseCount = (license.clauses ?? []).length;
  const obligationCount = (card.obligations ?? []).length;
  if (clauseCount > 0 && obligationCount === 0) {
    return {
      name: 'license',
      ok: false,
      message: `license clauses present but no obligations were derived`,
    };
  }
  if (clauseCount > 0 && obligationCount !== clauseCount) {
    return {
      name: 'license',
      ok: false,
      message: `expected one obligation per clause (${clauseCount}), derived ${obligationCount}`,
    };
  }

  return {
    name: 'license',
    ok: true,
    message: `license ${license.id} (${clauseCount} obligation(s))`,
  };
}

/** audit/settlement — rows well-formed, spend sums, valid terminal class. */
function validateSettlement(card: ContractCard): ValidationResult {
  const rows = card.spendLines ?? [];
  if (rows.length === 0) {
    return { name: 'settlement', ok: false, message: 'settlement has no spend lines' };
  }

  const spend: number[] = [];
  for (const [i, row] of rows.entries()) {
    if (typeof row.priceMicros !== 'number' || Number.isNaN(row.priceMicros)) {
      return { name: 'settlement', ok: false, message: `spend line ${i} has a non-numeric priceMicros` };
    }
    if (typeof row.settlementRef !== 'string' || row.settlementRef.length === 0) {
      return { name: 'settlement', ok: false, message: `spend line ${i} (${row.fetchId ?? `#${i}`}) has no settlementRef` };
    }
    spend.push(row.priceMicros);
  }

  if (card.status === 'fulfilled') {
    // We paid — a fulfilled row must prove it: a settlement ref for every
    // line, and the spend must reconcile with the recorded price.
    const summed = spend.reduce((acc, n) => acc + n, 0);
    if (card.price == null) {
      return { name: 'settlement', ok: false, message: 'a fulfilled outcome must carry a price' };
    }
    if (card.price.unitsMicros !== summed) {
      return {
        name: 'settlement',
        ok: false,
        message: `spend line sum ${summed} != recorded price ${card.price.unitsMicros}`,
      };
    }
  } else {
    // Denied rows carry failureClass (checked by contract-shape) and no spend.
    if (spend.length > 0) {
      return { name: 'settlement', ok: false, message: 'a denied outcome must not record spend lines' };
    }
  }

  return {
    name: 'settlement',
    ok: true,
    message: `settlement consistent across ${rows.length} line(s)`,
  };
}

/** contract-shape (gateway) — outcome shape, terminal class, denied class. */
function validateContractShape(card: ContractCard): ValidationResult {
  if (!card.content || typeof card.content.body !== 'string') {
    return { name: 'contract-shape', ok: false, message: 'content block is missing/invalid' };
  }
  if (!card.license) {
    return { name: 'contract-shape', ok: false, message: 'license block is missing' };
  }
  if (card.status === 'fulfilled' && (card.settlementRef == null || card.settlementRef.length === 0)) {
    return { name: 'contract-shape', ok: false, message: 'a fulfilled outcome must carry a settlementRef' };
  }

  // The terminal decision must be one of the four classes.
  const terminal = card.status === 'fulfilled' ? 'fulfilled' : card.failureClass;
  if (terminal == null || !TERMINAL_CLASSES.has(terminal)) {
    return {
      name: 'contract-shape',
      ok: false,
      message: `decision is not one of the 4 terminal classes: ${terminal}`,
    };
  }
  // A denied outcome must carry the correct failureClass.
  if (card.status !== 'fulfilled' && (card.failureClass == null || card.failureClass.length === 0)) {
    return { name: 'contract-shape', ok: false, message: 'a denied outcome must carry a failureClass' };
  }

  return {
    name: 'contract-shape',
    ok: true,
    message: `contract shape OK (${card.status === 'fulfilled' ? 'fulfilled' : card.failureClass})`,
  };
}

/**
 * The four validators, keyed to the public one-contract surface. Each reads
 * the card as plain data — no broker internals are imported.
 */
export const VALIDATORS: ReadonlyArray<[string, ValidatorFn]> = [
  ['identity', validateIdentity],
  ['license', validateLicense],
  ['settlement', validateSettlement],
  ['contract-shape', validateContractShape],
];
