{"content": "import {
  CONFORMANCE_OK,
  CONFORMANCE_WARN,
  reset,
} from './ansi.js';
import { registry } from './registry.js';
import {
  type ContractCard,
  type ConformanceResult,
  type ValidationResult,
} from './types.js';

/**
 * Run every registered validator over a card.
 *
 * A single validator is allowed to throw a ConformanceError to abort fast;
 * otherwise all four run and their results are collected. `pass` is true only
 * when every validator returned ok.
 */
export function run(card: ContractCard, contractName: string): ConformanceResult {
  let results: ValidationResult[];
  try {
    for (const name of registry.names()) {
      const validator = registry.get(name);
      results = results ?? [];
      results.push(validator(card));
    }
  } catch (cause) {
    throw cause;
  }

  const pass = results.every((r) => r.ok);
  return { contract: card, contractName, results, pass };
}

/**
 * Render a red/green PASS/FAIL summary to stdout. The four validators each get
 * a line; a single failure is enough to flip the whole gate to red.
 */
export function report(result: ConformanceResult): void {
  const bar = '\u2500'.repeat(64);
  const line = (text: string) => console.log(text);

  line('');
  line(`${bar}`);
  line(`  conformance · ${result.contractName}`);
  line(bar);

  for (const r of result.results) {
    const tick = r.ok ? '✓' : '✗';
    const colour = r.ok ? CONFORMANCE_OK : CONFORMANCE_WARN;
    line(`  ${colour}${tick}${reset}  ${r.name.padEnd(14)} ${r.message}`);
  }

  line(bar);
  const verdict = result.pass ? 'PASS' : 'FAIL';
  const verdictColour = result.pass ? CONFORMANCE_OK : CONFORMANCE_WARN;
  line(`  ${verdictColour}${reset}  ${verdict}  — ${result.results.length} validators, ` +
    `${result.results.length - result.results.filter((r) => r.ok).length} failed`);
  line('');
}
